"""Operational repair queue: one item per missing fact or return reason.

Organization (choice 4): items are grouped by responsible person, then by
subject. History is an append-only event list; item state is derived from it.
A batch that satisfies some, but not all, open items of one owner+subject group
is recorded as a partial response; the unsatisfied items stay open unchanged.
Drafts are written locally and never sent.
"""


def item_id(record_id):
    return "RQ-" + record_id[len("ISS-"):] if record_id.startswith("ISS-") else "RQ-" + record_id


class RepairQueue:
    def __init__(self, run_id):
        self.run_id = run_id
        self.items = {}    # item_id -> current item
        self.events = []   # append-only

    def _event(self, batch, kind, item, **extra):
        ev = {"seq": len(self.events) + 1, "run_id": self.run_id, "batch_id": "batch-%d" % batch, "event": kind,
              "item_id": item["item_id"] if item else None, **extra}
        self.events.append(ev)
        return ev

    def update(self, batch, issues, current_revisions, inputs_by_subject):
        """Apply this batch's open issues. Returns the events appended for the batch."""
        start = len(self.events)
        ref = {"run_id": self.run_id, "batch_id": "batch-%d" % batch}
        now = {item_id(i["record_id"]): i for i in issues}
        open_before = {k: v for k, v in self.items.items() if v["status"] == "open"}

        for iid, i in sorted(now.items()):
            fields = {"subject_type": i["subject_type"], "subject_id": i["subject_id"], "revision": i["revision"],
                      "trip_id": i["trip_id"], "trip_revision": i["trip_revision"], "permit_id": i["permit_id"],
                      "permit_revision": i["permit_revision"], "cost_id": i["cost_id"], "fact_code": i["fact_code"],
                      "missing_fact": i["reason"], "owner": i["owner"], "next_action": i["resolution_needed"],
                      "source_ids": i["source_ids"], "issue_record_id": i["record_id"]}
            cur = self.items.get(iid)
            if cur is None:
                prior = self._replaced(i)
                item = dict(fields, item_id=iid, status="open", opened=dict(ref), last_changed=dict(ref),
                            supersedes=prior["item_id"] if prior else None, superseded_by=None)
                if prior:
                    prior["superseded_by"] = iid
                self.items[iid] = item
                self._event(batch, "opened", item, owner=item["owner"], subject=i["subject_id"], revision=i["revision"],
                            fact=i["fact_code"], cost_id=i["cost_id"], supersedes=item["supersedes"],
                            source_ids=i["source_ids"], next_action=item["next_action"])
            elif cur["status"] != "open":
                cur.update(fields, status="open", last_changed=dict(ref))
                self._event(batch, "reopened", cur, owner=cur["owner"], subject=i["subject_id"], fact=i["fact_code"],
                            reason=i["reason"])
            else:
                changed = {k: fields[k] for k in ("owner", "next_action", "missing_fact") if cur[k] != fields[k]}
                if changed:
                    cur.update(fields, last_changed=dict(ref))
                    self._event(batch, "updated", cur, changes=changed)

        closed_by_group = {}
        for iid, item in sorted(open_before.items()):
            if iid in now:
                continue
            subj_rev = current_revisions.get((item["subject_type"], item["subject_id"]))
            if item["revision"] is not None and subj_rev is not None and subj_rev > item["revision"]:
                kind = "superseded"
            else:
                kind = "satisfied"
            item.update(status=kind, last_changed=dict(ref))
            evidence = inputs_by_subject.get(item["subject_id"], [])
            self._event(batch, kind, item, owner=item["owner"], subject=item["subject_id"], fact=item["fact_code"],
                        evidence=evidence, superseded_by=item.get("superseded_by"))
            closed_by_group.setdefault((item["owner"], item["subject_id"], item["revision"]), []).append(iid)

        for (owner, subj, rev), closed in sorted(closed_by_group.items(), key=lambda x: str(x[0])):
            remaining = sorted(k for k, v in self.items.items() if v["status"] == "open" and v["owner"] == owner
                               and v["subject_id"] == subj and v["revision"] == rev)
            if remaining:
                self._event(batch, "partial-response", None, owner=owner, subject=subj, revision=rev,
                            satisfied=sorted(closed), still_open=remaining)
        return self.events[start:]

    def _replaced(self, i):
        """Link a new-revision item to the same open fact on an earlier revision of the subject."""
        for it in self.items.values():
            if (it["subject_type"], it["subject_id"], it["fact_code"], it["cost_id"]) == (
                    i["subject_type"], i["subject_id"], i["fact_code"], i["cost_id"]) and it["revision"] is not None \
                    and i["revision"] is not None and it["revision"] < i["revision"] and it["superseded_by"] is None:
                return it
        return None

    def open_items(self):
        return sorted([v for v in self.items.values() if v["status"] == "open"],
                      key=lambda v: (v["owner"] or "", _nat(v["subject_id"]), v["item_id"]))

    def drafts(self):
        """{owner: markdown} request drafts, one per responsible person. Never sent."""
        by = {}
        for it in self.open_items():
            by.setdefault(it["owner"], []).append(it)
        out = {}
        for owner, items in by.items():
            lines = ["# DRAFT request to %s — not sent" % owner, "",
                     "Prepared locally by the travel-expense-claim Skill (run `%s`). A person must review and send it; "
                     "the Skill never sends requests." % self.run_id, ""]
            subj = None
            for it in items:
                key = (it["subject_type"], it["subject_id"], it["revision"])
                if key != subj:
                    subj = key
                    rev = " revision %s" % it["revision"] if it["revision"] is not None else ""
                    tr = " (trip %s r%s%s)" % (it["trip_id"], it["trip_revision"],
                                               ", permit %s r%s" % (it["permit_id"], it["permit_revision"]) if it["permit_id"] else "")
                    lines += ["## %s %s%s%s" % (it["subject_type"], it["subject_id"], rev, tr), ""]
                lines.append("- **%s**%s — %s. Requested: %s. Sources: %s. (`%s`, opened %s/%s)" % (
                    it["fact_code"], " for %s" % it["cost_id"] if it["cost_id"] else "", it["missing_fact"],
                    it["next_action"], ", ".join(it["source_ids"]), it["item_id"], it["opened"]["run_id"], it["opened"]["batch_id"]))
            out[owner] = "\n".join(lines) + "\n"
        return out


def _nat(s):
    import re
    return [int(x) if x.isdigit() else x for x in re.split(r"(\d+)", s or "")]

"""Run orchestration: capture -> engine -> sealed snapshots, queue, claims.csv, report.md."""
import csv
import datetime as dt
import hashlib
import io
import json
import os
import subprocess

from . import capture, dataset, engine, report
from .repair_queue import RepairQueue

SCHEMA_VERSION = "travel-claim-snapshot/2"


def canonical(obj):
    return (json.dumps(obj, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")


def write_sealed(path, obj):
    if os.path.exists(path):
        raise FileExistsError("refusing to overwrite sealed file " + path)
    data = canonical(obj)
    with open(path, "wb") as f:
        f.write(data)
    return hashlib.sha256(data).hexdigest()


def git_revision(repo):
    try:
        rev = subprocess.run(["git", "-C", repo, "rev-parse", "HEAD"], capture_output=True, text=True, check=True).stdout.strip()
        dirty = subprocess.run(["git", "-C", repo, "status", "--porcelain", "--", "skills"], capture_output=True, text=True).stdout.strip()
        return rev + ("+uncommitted-skill-changes" if dirty else "")
    except Exception:
        return None


def new_run_id(prefix):
    return "%s-%s" % (prefix, dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ"))


def execute(runs_dir, run_id, mode, replay_of=None, repo=None):
    run_dir = os.path.join(runs_dir, run_id)
    if os.path.exists(run_dir):
        raise FileExistsError("run %s already exists; runs are never overwritten" % run_id)
    os.makedirs(os.path.join(run_dir, "batches"))
    started = capture.utcnow()

    if mode == "fresh":
        files = capture.flatten(capture.capture_fresh(run_dir))
    else:
        prior_dir = os.path.join(runs_dir, replay_of)
        prior = json.load(open(os.path.join(prior_dir, "sources.json"), encoding="utf-8"))
        files = capture.capture_replay(run_dir, prior_dir, prior)

    meta = {"run_id": run_id, "mode": mode, "replay_of": replay_of, "started_at": started,
            "code_revision": git_revision(repo or "."), "outcome": None}
    try:
        ds = dataset.load(run_dir, files)
        clock = "%s %s" % (ds["policy"]["case_clock_date"], ds["policy"]["case_clock_tz"])
    except dataset.SourceUnavailable as e:
        ds, clock = None, None
        meta["outcome"] = "failure"
        meta["failure"] = str(e)

    sources = {"run_id": run_id, "mode": "fresh-read" if mode == "fresh" else "offline-replay",
               "replay_of": replay_of, "source_version": _source_version(files), "case_clock": clock,
               "files": files, "limitations": _limitations(files, ds)}
    src_sha = write_sealed(os.path.join(run_dir, "sources.json"), sources)

    if ds is None:
        meta["finished_at"] = capture.utcnow()
        write_sealed(os.path.join(run_dir, "run.json"), meta)
        with open(os.path.join(run_dir, "report.md"), "w", encoding="utf-8") as f:
            f.write(report.failure_report(meta, sources))
        return run_dir, meta

    eng = engine.Engine(ds)
    rq = RepairQueue(run_id)
    snaps, prev, history = [], None, []

    def on_batch(b, state):
        nonlocal prev
        snap, issues = build_snapshot(run_id, b, prev, src_sha, eng, state)
        rel = "batches/batch-%d.json" % b
        sha = write_sealed(os.path.join(run_dir, rel), snap)
        prev = {"path": rel, "sha256": sha}
        cur_revs = {("claim", cid): c["revision"] for cid, c in eng.current.items()}
        inputs = {}
        for x in eng.batch_log[b]:
            inputs.setdefault(x["subject"], []).extend(x["refs"])
        q_events = rq.update(b, issues, cur_revs, inputs)
        snaps.append({"batch": b, "path": rel, "sha256": sha, "snapshot": snap, "queue_events": q_events,
                      "log": list(eng.batch_log[b])})
        history.append(state)

    eng.run(on_batch)

    qdir = os.path.join(run_dir, "queue")
    os.makedirs(os.path.join(qdir, "drafts"))
    with open(os.path.join(qdir, "events.jsonl"), "w", encoding="utf-8") as f:
        for ev in rq.events:
            f.write(json.dumps(ev, ensure_ascii=False, sort_keys=True) + "\n")
    with open(os.path.join(qdir, "items.json"), "wb") as f:
        f.write(canonical(sorted(rq.items.values(), key=lambda v: v["item_id"])))
    for owner, md in rq.drafts().items():
        with open(os.path.join(qdir, "drafts", "%s.md" % owner), "w", encoding="utf-8") as f:
            f.write(md)

    final = snaps[-1]["snapshot"]
    with open(os.path.join(run_dir, "claims.csv"), "w", encoding="utf-8", newline="") as f:
        f.write(claims_csv(final))

    partial = [x for x in files if x["status"] != "read" or x.get("completeness") != "complete"]
    meta["outcome"] = "partial" if (partial or ds["limits"]) else "success"
    meta["batches"] = [{"batch_id": "batch-%d" % s["batch"], "path": s["path"], "sha256": s["sha256"]} for s in snaps]
    meta["finished_at"] = capture.utcnow()
    with open(os.path.join(run_dir, "report.md"), "w", encoding="utf-8") as f:
        f.write(report.build(meta, sources, snaps, eng, rq, ds))
    write_sealed(os.path.join(run_dir, "run.json"), meta)
    return run_dir, meta


def build_snapshot(run_id, b, prev, src_sha, eng, state):
    claims, issues = [], {}
    for cid, st in state["claims"].items():
        claims.append({k: st[k] for k in ("claim_id", "revision", "trip_id", "trip_revision", "status", "lines",
                                          "allowed_cents", "paid_cents", "balance_cents", "decision_ids",
                                          "next_owner", "reason")})
        for i in st["issues"]:
            issues.setdefault(i["record_id"], i)
    cancs = []
    for k, cs in state["cancellations"].items():
        for i in cs["issues"]:
            issues.setdefault(i["record_id"], i)
        row = {x: cs[x] for x in cs if x != "issues"}
        row["issue_record_ids"] = sorted({i["record_id"] for i in cs["issues"]})
        cancs.append(row)
    reqs = [{k: r[k] for k in ("request_id", "claim_id", "revision", "amount_cents", "payee", "currency",
                               "status", "decision_ids")} for r in sorted(eng.requests.values(), key=lambda r: engine._natural(r["request_id"]))]
    snap = {"schema_version": SCHEMA_VERSION, "run_id": run_id, "batch_id": "batch-%d" % b, "predecessor": prev,
            "source_binding": {"path": "sources.json", "sha256": src_sha}, "claims": claims, "requests": reqs,
            "travel_cancellations": cancs,
            "admitted_event_ids": [e["event_id"] for e in eng.fin_admitted],
            "issues": [{"record_id": i["record_id"], "reason": i["reason"], "owner": i["owner"] or "UNASSIGNED",
                        "resolution_needed": i["resolution_needed"]} for i in sorted(issues.values(), key=lambda i: i["record_id"])]}
    return snap, list(issues.values())


def claims_csv(snap):
    buf = io.StringIO()
    w = csv.writer(buf, lineterminator="\n")
    w.writerow(["claim_id", "revision", "trip_id", "status", "allowed_cents", "paid_cents", "balance_cents", "next_owner", "reason"])
    for c in snap["claims"]:
        w.writerow([c["claim_id"], c["revision"], c["trip_id"], c["status"],
                    "" if c["allowed_cents"] is None else c["allowed_cents"], c["paid_cents"],
                    "" if c["balance_cents"] is None else c["balance_cents"], c["next_owner"] or "", c["reason"]])
    return buf.getvalue()


def _source_version(files):
    h = hashlib.sha256()
    for f in sorted(files, key=lambda f: f["source_id"]):
        h.update(("%s=%s;" % (f["source_id"], f["sha256"])).encode())
    return "content-set-sha256:" + h.hexdigest()


def _limitations(files, ds):
    out = [
        "Policy paragraph 1 says 'Read the fixed source manifest before each run' and cites LOG-0014. The operations lead "
        "confirmed in interview 2 (10:03, 10:11) that no such document exists and instructed us to proceed with the five "
        "native sources (10:12). The reference stays recorded here as unresolved.",
        "The workbook and the PDFs expose no native revision identifier (interview 2, 10:09). Their `version` is the HTTP "
        "validator the server returned, or null; identity is the retained bytes' sha256 plus retrieval time and locator.",
        "DW-D-2 (cited by every review) is the business workflow contract whose rules are contained in the policy "
        "(interview 2, 10:08); it is not a separate fetchable source.",
    ]
    for f in files:
        if f["status"] != "read" or f.get("completeness") != "complete":
            out.append("%s: %s (%s)" % (f["source_id"], f.get("missing_scope") or f["status"], f.get("error")))
    if ds:
        out += ds["limits"]
    return out

